map.on('click',e=>{if(!ready)return;if(mode==='point'){origin=turf.point([e.lngLat.lng,e.lngLat.lat]);invalidate();updateOrigin();$('selection').textContent=`Ponto: ${e.lngLat.lat.toFixed(4)}°, ${e.lngLat.lng.toFixed(4)}°. Gere a análise.`;setMode('inspect');return;}if(mode==='polygon'){vertices.push([e.lngLat.lng,e.lngLat.lat]);draft();return;}const hit=map.queryRenderedFeatures(e.point,{layers:['wind-line','poly-fill']});if(hit.length&&result)popup(hit[0],e.lngLat);});
