$('torre').onclick=()=>{origin=turf.point(TORRE);invalidate();updateOrigin();setMode('inspect');$('selection').textContent='Origem: Torre, Serra da Estrela.';map.flyTo({center:TORRE,zoom:12.3,pitch:60,bearing:-28});generate();};
