for(const id of ['hour','day','direction','speed','travelBearing'])$(id).addEventListener('input',changed);
$('travelMode').onchange=()=>{$('travelBearing').disabled=$('travelMode').value!=='fixed';changed();};
$('layer').onchange=applyLayer;$('tilt').onclick=()=>{const flat=map.getPitch()<10;map.easeTo({pitch:flat?60:0,bearing:flat?-28:0});$('tilt').textContent=flat?'Vista 2D':'Vista 3D';};
for(const [id,layers] of [['links',['edge-line']],['arrows',['wind-line']]])$(id).onchange=()=>{if(ready)for(const l of layers)map.setLayoutProperty(l,'visibility',$(id).checked?'visible':'none');};
$('labels').onchange=()=>labelMarkers.forEach(m=>m.getElement().style.display=$('labels').checked?'':'none');
$('resetWind').onclick=()=>{windPoints=null;windMeta=null;$('direction').disabled=false;$('speed').disabled=false;$('windFile').value='';$('windSource').textContent='Uniforme e definido pelo utilizador · não é WindNinja.';changed();};
$('windFile').onchange=async()=>{const file=$('windFile').files[0];if(!file)return;try{if(file.size>8e6)throw new Error('Máximo 8 MB.');const data=JSON.parse(await file.text());if(data.type!=='FeatureCollection'||!Array.isArray(data.features)||!data.features.length||data.features.length>10000)throw new Error('FeatureCollection com 1–10 000 pontos necessária.');if(typeof data.wind_source!=='string'||!data.wind_source.trim()||!Number.isFinite(data.height_m)||data.height_m<=0||typeof data.valid_time!=='string'||!/(Z|[+-]\d\d:\d\d)$/.test(data.valid_time)||!Number.isFinite(Date.parse(data.valid_time)))throw new Error('Indique wind_source, height_m > 0 e valid_time ISO com fuso no topo do GeoJSON.');for(const p of data.features){const c=p.geometry?.coordinates;if(p.geometry?.type!=='Point'||!Array.isArray(c)||!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>75||!Number.isFinite(p.properties?.u)||!Number.isFinite(p.properties?.v)||Math.hypot(p.properties.u,p.properties.v)>100)throw new Error('Pontos WGS84 e propriedades u/v numéricas em m/s (≤100 m/s) necessárias.');}windPoints=data.features;windMeta={source:data.wind_source,valid_time:data.valid_time,height_m:data.height_m,filename:file.name,interpolation:'nearest <=1 km',verified:false};$('direction').disabled=true;$('speed').disabled=true;$('windSource').textContent=`Campo importado · ${data.features.length} vetores · ${data.height_m} m · válido ${data.valid_time}. Hora solar independente; o vento mantém esta validade.`;changed();}catch(e){status(`Importação recusada: ${e.message}`);$('windFile').value='';}};
$('export').onclick=()=>{if(!result)return;const features=[{...result.metadata.origin,properties:{kind:'origin'}},...result.polys.features.map(f=>({...f,properties:{...f.properties,kind:'potential_polygon'}})),...result.edges.features,...result.wind.features,...result.prop.features];const blob=new Blob([JSON.stringify({...fc(features),metadata:result.metadata},null,2)],{type:'application/geo+json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`cps-potenciais-${result.metadata.valid_time.replaceAll(':','-')}.geojson`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
window.addEventListener('error',e=>{status(`Erro da aplicação: ${e.message}. Verifique acesso à Internet e recarregue.`);});
window.addEventListener('unhandledrejection',e=>{status(`Falha ao carregar: ${e.reason?.message||e.reason}. Verifique acesso à Internet.`);});
